-- T-Jet · base completa de veículos (FIPE) · rode uma vez no SQL Editor do Supabase
-- gerado em 20/08/2026 a partir da API pública da FIPE (parallelum.com.br)

create table if not exists tjet_veiculos_fipe (
  id      bigserial primary key,
  marca   text not null,
  modelo  text not null,
  porte   text not null
);

create index if not exists tjet_veiculos_fipe_marca on tjet_veiculos_fipe (marca);
create index if not exists tjet_veiculos_fipe_modelo_lower on tjet_veiculos_fipe (lower(modelo));

alter table tjet_veiculos_fipe enable row level security;
drop policy if exists tjet_veiculos_fipe_leitura on tjet_veiculos_fipe;
create policy tjet_veiculos_fipe_leitura on tjet_veiculos_fipe
  for select to anon using (true);

-- esvazia antes de repovoar (permite rodar este arquivo de novo numa atualização futura)
truncate table tjet_veiculos_fipe;

